head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.gDepCd = js_dep_cd;
scwin.gDutyGrp = js_gduty;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gEmpNo = js_emp_no; // 세션정보 
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.gProcsCd = ""; //사후처리상태코드
scwin.gProcsNm = ""; //상태코드 메시지

scwin.vScrenID = 'ULDSTF10108.xml';

// 부모창(목록검색)의 접수번호
//var gAcptNo = frame.Provider("/").gAcptNo;
scwin.gAcptNo = $c.frame.path("../frame_head").scwin.gAcptNo;
scwin.gSndlocTp = $c.frame.path("../frame_head").gSndlocTpCd;
scwin.gProcsStatCd = $c.frame.path("../frame_head").scwin.gProcsStatCd; // 처리상태
scwin.gAffProcsStatCd = $c.frame.path("../frame_head").scwin.gAffProcsStatCd; //  사후 처리상태
scwin.gDoc_LdMktTp = $c.frame.path("../frame_head").scwin.gDoc_LdMktTp;
scwin.gDisclsAcptTpCd = $c.frame.path("../frame_head").scwin.gDisclsAcptTpCd; // 공시접수유형
scwin.gDisclsTrnsmTpCd = $c.frame.path("../frame_head").scwin.gDisclsTrnsmTpCd; // 전송구분
scwin.gDelayYn = $c.frame.path("../frame_head").scwin.gDelayYn; // 처리지연 상태여부
scwin.gFormWarnContn = $c.frame.path("../frame_head").scwin.gFormWarnContn;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //공동공시 유의사항

scwin.fn_showOptButton = function() {
    // 1. 승인 및 정정요구승인, 재검토요구  버튼 생성
    if (scwin.gAffProcsStatCd == '10') {
        // 검토상태			
        $c.stf.showObj(img_approval, true); // 승인 show
        $c.stf.showObj(img_review, true); // 재검토요구  show	
        $c.stf.showObj(img_affreqapprov, false); // 승인 hidden

    } else if (scwin.gAffProcsStatCd == '20') {
        //정정요구검토
        $c.stf.showObj(img_approval, false); // 승인 show
        $c.stf.showObj(img_affreqapprov, true); // 승인 hidden
        $c.stf.showObj(img_review, true); // 재검토요구  show		

    } else {
        $c.stf.showObj(img_approval, false); // 승인 hidden
        $c.stf.showObj(img_affreqapprov, false); // 정정요구검토	hidden
        $c.stf.showObj(img_review, false); // 재검토요구  hidden		

    }
};



/*
 * 로그인 사용자정보로 공시처리가능여부 체크
 *  => 팀장(or 부서장)은 팀구분은 없다.
 */
scwin.fn_getApprvProcButtonYN = function() {
    var url = "/Viewer.do?method=getProcBtnShowYn" + "&inputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&outputMessageId=VIEWER_PROCBTNSHOWYN_INOUT" + "&ACPT_NO=" + scwin.gAcptNo + "&DUTY_GRP_TP=" + scwin.gDutyGrp + "&DEP_CD=" + scwin.gDepCd;
    dts_btnshow.DataID = encodeURI(url);
    dts_btnshow.reset();
};


// 책임자처리시 :  처리버튼 생성여부 
scwin.fn_showApprvProcButton = function(pDutyProcYn, pGrnlProcYn, pCloseYn) {
    if (scwin.gAcptNo != '') {
        // 가져온접수번호가 있으면 처리함.
        // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
        //if (gJobTitle == '09' || gJobTitle == '40' || gDutyYn == 'Y' || gDutyChrg == 'Y') {
        if (scwin.gJobTitle != '40' && (scwin.gJobTitle == '09' || scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y')) {
            //부서장권한 제거 2013.03.26
            // 마감전일때
            if (pCloseYn == 'N') {
                if (scwin.gFormWarnContn != "") {
                    label_WARN_CONTN.childNodes[0].innerText = scwin.gFormWarnContn;
                }

                // 로그한 사용자가 당번이면서 접수문서가 당번그룹에 해당할 경우
                if (pDutyProcYn == 'Y') {
                    // 패널라운드 처리
                    $c.cm.PanelToGroupBox(panel_2);
                    $c.stf.showObj(panel_1, true);
                } else {
                    /*
                    // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                    if (pGrnlProcYn == 'Y') {
                    	// 패널라운드 처리	
                    	PanelToGroupBox(panel_1);	
                    	showObj(panel_1, true);
                    } else {
                    	showObj(panel_1, false);
                    }
                    */
                    // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.
                    $c.cm.PanelToGroupBox(panel_2); // 패널라운드 처리
                    $c.stf.showObj(panel_1, true);
                }
            } else {
                // 마감후일때
                $c.stf.showObj(panel_1, false);
            }
        } else {
            // 팀장이 아닐때
            $c.stf.showObj(panel_1, false);
        }
    }
};




// 처리상태 조회하기
scwin.fn_getProcsSate = function(gAcptNo) {
    var url = "/DisclosureStudyAffact.do?method=getDsclProcsStatAffact" + "&inputMessageId=VIEWER_OUT" + "&outputMessageId=VIEWER_OUT" + "&ACPT_NO=" + scwin.gAcptNo;
    dts_procs_stat.DataID = encodeURI(url);
    dts_procs_stat.reset();
    var vAFF_PROCS_STAT_CD = dts_procs_stat.getCellData(1, "AFF_PROCS_STAT_CD");
    var vAFF_PROCS_STAT_NM = dts_procs_stat.getCellData(1, "AFF_PROCS_STAT_NM");
    var vAFF_PROCS_DDTM = dts_procs_stat.getCellData(1, "AFF_PROCS_DDTM");
    if (scwin.gAffProcsStatCd != vAFF_PROCS_STAT_CD) {
        $c.win.alert("본 공시가 " + vAFF_PROCS_DDTM + "에  이미 [" + vAFF_PROCS_STAT_NM + "] 처리가 되었습니다.");
        //fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};



//사후  승인 처리하기 
scwin.fn_DsclApproval = function(gStatCd, gStatNm) {
    if (scwin.gAcptNo == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    dts_AcptProcs.insertRow();
    dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptProcs.setCellData(1, "AFFACT_PROCS_STAT_CD", gStatCd);
    dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    if (dts_AcptProcs.getCellData(1, "ACPT_NO") == '') {
        $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    var vAnswer = confirm(gStatNm + " 하시겠습니까?");
    if (vAnswer == true) {
        if (scwin.fn_getProcsSate(scwin.gAcptNo) == false) {
            scwin.fn_CloseParentReload();
            return false;
        } else {
            trs_AcptProcs.Action = "/DisclosureStudyAffact.do?method=procDsclApprovAffact&inputMessageId=DSCLPROC_AFFACT_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo;
            trs_AcptProcs.KeyName = "toinb_dataid4";
            trs_AcptProcs.KeyValue = "JSP(I:pInput=dts_AcptProcs)";
            trs_AcptProcs.Post();
        }
    }
};





// 뷰어 닫고,  검색목록 reload
scwin.fn_CloseParentReload = function() {
    // 화면닫기
    $c.frame.path("../").fn_PvdSearch();
    $c.frame.path("../").fn_CloseWin();
};
scwin.dts_btnshow_OnLoadCompleted = function(rowcount) {
    scwin.fn_showApprvProcButton(dts_btnshow.getCellData(1, "DUTY_PROC_YN"), dts_btnshow.getCellData(1, "GRNL_PROC_YN"), dts_btnshow.getCellData(1, "CLOSE_YN"));
};
scwin.dts_btnshow_OnLoadError = function() {
    //alert('dts_btnshow.OnFail() :' + dts_btnshow.ErrorMsg);
    $c.win.alert("사용자 정보를 가져오는데 실패하였습니다.");
};
scwin.dts_procs_stat_OnLoadCompleted = function(rowcount) {

};
scwin.dts_procs_stat_OnLoadError = function() {
    //alert('dts_procs_stat.OnLoadError()'+ dts_procs_stat.ErrorMsg);
    $c.win.alert("처리상태를 가져오는데 실패하였습니다.");
};
scwin.trs_AcptProcs_OnSuccess = function() {
    $c.win.alert("성공적으로 " + scwin.gProcsNm + " 처리 되었습니다.");
    scwin.fn_CloseParentReload();
};
scwin.trs_AcptProcs_OnFail = function() {
    //alert('trs_AcptProcs.OnFail() :' + trs_AcptProcs.ErrorMsg);
    $c.win.alert(scwin.gProcsNm + " 처리에 실패하였습니다.");
};
scwin.trs_Review_OnSuccess = function() {
    $c.win.alert("성공적으로 재검토요구 처리가 되었습니다.");
    scwin.fn_CloseParentReload();
};
scwin.trs_Review_OnFail = function() {
    //alert('trs_Review.OnFail() :' + trs_Review.ErrorMsg);
    $c.win.alert("재검토요구 처리에 실패하였습니다.");
};
scwin.img_approval_onclick = function() {
    scwin.gProcsCd = "30";
    scwin.gProcsNm = "사후승인";
    scwin.fn_DsclApproval(scwin.gProcsCd, scwin.gProcsNm);
};
scwin.img_affreqapprov_onclick = function() {
    scwin.gProcsCd = "40";
    scwin.gProcsNm = "정정요구승인";
    scwin.fn_DsclApproval(scwin.gProcsCd, scwin.gProcsNm);
};
scwin.img_review_onclick = function() {
    scwin.gProcsCd = "01";
    scwin.gProcsNm = "재검토요구";
    scwin.fn_DsclApproval(scwin.gProcsCd, scwin.gProcsNm);
};
scwin.img_close_onclick = function() {
    $c.frame.path("../").fn_CloseWin();
};
scwin.img_print_onclick = function() {
    //fn_PrintFormCall();
    $c.frame.path("../frame_head").fn_PrintOpen();
};
scwin.gform_onload = function() {
    // 로그인 사용자정보로 공시처리가능여부 체크 
    scwin.fn_getApprvProcButtonYN();

    // 가우스헤더 셋팅
    dts_AcptProcs.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLPROC_AFFACT_IN";
    dts_AcptProcs.reset();

    // 이전단계 처리상태에 따른 버튼 생성여부
    scwin.fn_showOptButton();
};
